import { Component, inject, OnInit, signal, ChangeDetectorRef, DestroyRef } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router, ActivatedRoute, RouterLink } from '@angular/router';
import { QuillModule } from 'ngx-quill';
import { ReporteTrimestralService } from '../../../../shared/services/reporte-trimestral.service';
import { ReporteTrimestral } from '../../../../shared/models/reporte-trimestral.model';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { environment } from '../../../../../environments/environment';
import { Solicitud } from '../../../../shared/models/solicitud.model';
import { ToastService } from '../../../../shared/services/toast.service';
import { extractErrorMessage } from '../../../../shared/utils/error-utils';

@Component({
  selector: 'app-reportes-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, RouterLink, QuillModule],
  templateUrl: './reportes-form.component.html'
})
export class ReportesFormComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly reporteService = inject(ReporteTrimestralService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly http = inject(HttpClient);

  form: FormGroup;
  isEditMode = false;
  isSubmitting = false;
  reporteId?: number;
  solicitudesAprobadas = signal<Solicitud[]>([]);

  constructor() {
    this.form = this.fb.group({
      solicitud_id: ['', Validators.required],
      titulo: ['', [Validators.required, Validators.maxLength(255)]],
      contenido: ['', Validators.required]
    });
  }

  ngOnInit(): void {
    this.cargarSolicitudesAprobadas();
    
    const idParam = this.route.snapshot.paramMap.get('id');
    if (idParam && idParam !== 'nuevo') {
      this.isEditMode = true;
      this.reporteId = +idParam;
      this.cargarReporte(this.reporteId);
    } else {
      const solicitudIdParam = this.route.snapshot.queryParamMap.get('solicitud_id');
      if (solicitudIdParam) {
        this.form.patchValue({ solicitud_id: +solicitudIdParam });
      }
    }
  }

  private readonly cdr = inject(ChangeDetectorRef);
  private readonly toast = inject(ToastService);
  private readonly destroyRef = inject(DestroyRef);

  cargarSolicitudesAprobadas(): void {
    this.http.get<{data: Solicitud[]} | Solicitud[]>(`${environment.apiUrl}/solicitudes?status=Autorizada,En Seguimiento,Aprobada`).pipe(
      takeUntilDestroyed(this.destroyRef)
    ).subscribe({
      next: (res) => {
        // Depending on pagination structure
        this.solicitudesAprobadas.set(('data' in res) ? res.data : res);
        this.cdr.markForCheck();
      },
      error: (err: HttpErrorResponse) => {
        this.toast.error(extractErrorMessage(err));
        console.error('Error loading solicitudes:', err);
      }
    });
  }

  cargarReporte(id: number): void {
    this.reporteService.getReporte(id).pipe(
      takeUntilDestroyed(this.destroyRef)
    ).subscribe({
      next: (reporte: ReporteTrimestral) => {
        this.form.patchValue({
          solicitud_id: reporte.solicitud_id,
          titulo: reporte.titulo,
          contenido: reporte.contenido
        });
      },
      error: (err: HttpErrorResponse) => {
        this.toast.error(extractErrorMessage(err));
        console.error('Error', err);
        this.router.navigate(['/inversores/reportes']);
      }
    });
  }

  onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.isSubmitting = true;
    const data = this.form.value;

    if (this.isEditMode && this.reporteId) {
      this.reporteService.actualizarReporte(this.reporteId, data).subscribe({
        next: () => {
          this.toast.success('Reporte actualizado correctamente.');
          this.router.navigate(['/inversores/reportes']);
        },
        error: (err: HttpErrorResponse) => {
          this.toast.error(extractErrorMessage(err));
          console.error('Error actualizando', err);
          this.isSubmitting = false;
        }
      });
    } else {
      this.reporteService.crearReporte(data).subscribe({
        next: () => {
          this.toast.success('Reporte creado correctamente.');
          this.router.navigate(['/inversores/reportes']);
        },
        error: (err: HttpErrorResponse) => {
          this.toast.error(extractErrorMessage(err));
          console.error('Error creando', err);
          this.isSubmitting = false;
        }
      });
    }
  }
}